#!/bin/bash
# CloudQuant: 1-Click AWS CloudShell Automated Provisioner for ap-south-1
set -euo pipefail

REGION="ap-south-1"
echo "==> [1/5] Verifying AWS Identity in CloudShell..."
aws sts get-caller-identity --output table

echo "==> [2/5] Locating VPC in $REGION..."
VPC_ID=$(aws ec2 describe-vpcs --region "$REGION" --filters "Name=isDefault,Values=true" --query "Vpcs[0].VpcId" --output text)
if [ -z "$VPC_ID" ] || [ "$VPC_ID" == "None" ]; then
  VPC_ID=$(aws ec2 describe-vpcs --region "$REGION" --query "Vpcs[0].VpcId" --output text)
fi
echo "Target VPC: $VPC_ID"

echo "==> [3/5] Configuring Security Group (Allowing Port 8501)..."
SG_ID=$(aws ec2 describe-security-groups --region "$REGION" --filters "Name=group-name,Values=cloudquant-sg" "Name=vpc-id,Values=$VPC_ID" --query "SecurityGroups[0].GroupId" --output text 2>/dev/null || true)
if [ -z "$SG_ID" ] || [ "$SG_ID" == "None" ]; then
  SG_ID=$(aws ec2 create-security-group --region "$REGION" --group-name cloudquant-sg --description "CloudQuant Streamlit App" --vpc-id "$VPC_ID" --query "GroupId" --output text)
  aws ec2 authorize-security-group-ingress --region "$REGION" --group-id "$SG_ID" --protocol tcp --port 8501 --cidr 0.0.0.0/0
  echo "Created Security Group: $SG_ID"
else
  echo "Using existing Security Group: $SG_ID"
fi

echo "==> [4/5] Resolving latest Amazon Linux 2023 AMI..."
AMI_ID=$(aws ssm get-parameter --region "$REGION" --name "/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64" --query "Parameter.Value" --output text)
echo "Using AMI: $AMI_ID"

echo "==> [5/5] Provisioning EC2 t3.micro (Free Tier / <$0.39) with automated setup..."
cat << 'PAYLOAD_EOF' > /tmp/user_data.sh
#!/bin/bash
set -euo pipefail
exec > /var/log/cloudquant-install.log 2>&1

echo '==> Starting CloudQuant Automated Provisioning on AWS EC2...'
dnf update -y
dnf install -y python3.11 python3.11-pip git

APP_DIR='/home/ec2-user/cloudquant'
mkdir -p "$APP_DIR"
mkdir -p "$APP_DIR/deploy"
cd "$APP_DIR"

echo 'c3RyZWFtbGl0Pj0xLjMwLjAKcGFuZGFzPj0yLjAuMApudW1weT49MS4yNC4wCnlmaW5hbmNlPj0wLjIuMzUKcGxvdGx5Pj01LjE4LjAKcHl0ZXN0Pj03LjQuMAo=' | base64 -d > "$APP_DIR/requirements.txt"
echo '' | base64 -d > "$APP_DIR/database.py"
echo '' | base64 -d > "$APP_DIR/market_data.py"
echo '' | base64 -d > "$APP_DIR/strategy.py"
echo '' | base64 -d > "$APP_DIR/trading_engine.py"
echo '' | base64 -d > "$APP_DIR/app.py"
echo '' | base64 -d > "$APP_DIR/deploy/cloudquant.service"

python3.11 -m venv .venv
source .venv/bin/activate
pip install --upgrade pip
pip install -r requirements.txt

python -c 'import database; database.init_db()'
chown -R ec2-user:ec2-user "$APP_DIR"

cp deploy/cloudquant.service /etc/systemd/system/cloudquant.service
systemctl daemon-reload
systemctl enable cloudquant.service
systemctl restart cloudquant.service

echo '==> CloudQuant successfully installed and running on port 8501!'

PAYLOAD_EOF

INSTANCE_ID=$(aws ec2 run-instances   --region "$REGION"   --image-id "$AMI_ID"   --instance-type "t3.micro"   --security-group-ids "$SG_ID"   --block-device-mappings '[{"DeviceName":"/dev/xvda","Ebs":{"VolumeSize":8,"VolumeType":"gp3","DeleteOnTermination":true}}]'   --tag-specifications 'ResourceType=instance,Tags=[{Key=Name,Value=cloudquant-prod},{Key=Project,Value=CloudQuant}]'   --user-data file:///tmp/user_data.sh   --query "Instances[0].InstanceId"   --output text)

echo "Provisioned EC2 Instance: $INSTANCE_ID"
echo "Waiting for instance to initialize and receive Public IP..."
aws ec2 wait instance-running --region "$REGION" --instance-ids "$INSTANCE_ID"

PUBLIC_IP=$(aws ec2 describe-instances --region "$REGION" --instance-ids "$INSTANCE_ID" --query "Reservations[0].Instances[0].PublicIpAddress" --output text)

echo ""
echo "======================================================================"
echo "🎉 CLOUDQUANT DEPLOYED SUCCESSFULLY ON AWS!"
echo "Instance ID : $INSTANCE_ID"
echo "Public IPv4 : $PUBLIC_IP"
echo "Live Web URL: http://${PUBLIC_IP}:8501"
echo "======================================================================"
echo "Application bootstrap will complete in 2 minutes."
